export type Message<T extends string = string, D = unknown> = { type: T; data: D };
export type Ctx = { newId(): string; now(): Date; flag(name: string): boolean };
export interface Decider<State, C extends Message, E extends Message> {
  initial: State;
  evolve(state: State, event: E): State;                 // no rules
  decide(state: State, command: C, ctx: Ctx): E[] | Rejection; // the only function with rules
}
export const defineCommand = (type, fields) => (data) => Message;   // Schema-validated at the boundary
export const defineEvent   = (type, fields) => (data) => Message;

export type Statement = { readonly sql: string; readonly params: ReadonlyArray<unknown> };
export class WriteConflict extends Schema.TaggedError<WriteConflict>()('WriteConflict', { message: Schema.String }) {}
export class Sql extends Context.Service<Sql, {
  readonly dialect: 'sqlite' | 'postgres';
  query<R>(sql: string, params?: ReadonlyArray<unknown>): Effect.Effect<R[]>;
  atomically(statements: ReadonlyArray<Statement>): Effect.Effect<void, WriteConflict>; // all or none
}>()('greenhouse/engine/Sql') {}

export type Projection = { name: string; tables: ReadonlyArray<string>; on(event: Recorded): ReadonlyArray<Statement> };
class EventStore extends Context.Service<EventStore, {
  setup(): Effect<void>;
  read(stream: string): Effect<Recorded[]>;
  append(stream, expected: number, events, meta: { by; at }): Effect<Recorded[], WriteConflict>;
  execute(decider, stream, command, ctx, by): Effect<Recorded[] | Rejection, WriteConflict>; // read, decide, append
}> { static layer(projections: ReadonlyArray<Projection>): Layer<EventStore, never, Sql> }

hashPassword(password: string): Promise<string>;            // pbkdf2$100000$<salt>$<hash>
verifyPassword(password: string, stored: string): Promise<boolean>;
newToken(): string;  tokenHash(token: string): Promise<string>;
DECOY: string;  // verified against when the email is unknown

CREATE TABLE IF NOT EXISTS accounts (account_id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL,
  admin INTEGER NOT NULL DEFAULT 0, password_hash TEXT NOT NULL, opened_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sign_ins (token_hash TEXT PRIMARY KEY, account_id TEXT NOT NULL,
  signed_in_at TEXT NOT NULL, expires_at TEXT NOT NULL);

class Accounts extends Context.Service<Accounts, {
  signUp(body: unknown): Effect<Account, SignUpRefused>;        // password of at least 12 characters
  open(input: { email; name; password; admin }): Effect<Account, SignUpRefused>;
  signIn(body: unknown): Effect<{ token: string; account: Account }, SignInFailed>;  // 30 days
  accountFor(token: string): Effect<Account | undefined>;
  signOut(token: string): Effect<void>;
}>

// POST /auth/sign-up  { email, name, password }  → 201 { account } | 409 { rejected }
// POST /auth/sign-in  { email, password }        → 200 { account, token } + gh_session cookie | 401 { rejected }
// POST /auth/sign-out                            → 200 { ok: true }; ends this sign-in only
// GET  /auth/me                                  → 200 { account } | 401 { rejected: 'not signed in' }
export const tokenOf: (authorization?: string, cookie?: string) => string | undefined; // Bearer first
export const requireSignIn: MiddlewareHandler; // 401 without a live sign-in; sets c.var.account

